def transform(grid):
    h, w = len(grid), len(grid[0])

    # The background is the most common color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Full uniform rows and columns are the separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    wall_colors = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    wall = max(set(wall_colors), key=wall_colors.count)

    marker_counts = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != background and value != wall:
                marker_counts[value] = marker_counts.get(value, 0) + 1
    marker = max(marker_counts, key=marker_counts.get)

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    output = []
    for i in range(len(row_bounds) - 1):
        out_row = []
        for j in range(len(col_bounds) - 1):
            r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            n = sum(grid[r][c] == marker
                    for r in range(r0, r1) for c in range(c0, c1))
            out_row.append(1 if n >= 2 else background)
        output.append(out_row)
    return output
